#include "opensim/scene/avatar_packets.hpp"
#include "opensim/scene/default_animations.hpp"
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace opensim;using namespace scene;
static std::string hex(const std::vector<std::uint8_t>& bytes){std::ostringstream s;for(auto b:bytes)s<<std::hex<<std::setfill('0')<<std::setw(2)<<unsigned(b);return s.str();}
static std::string unhex(const std::string& text){if(text=="-")return {};std::string result;for(std::size_t i=0;i<text.size();i+=2)result+=char(std::stoi(text.substr(i,2),nullptr,16));return result;}
static framework::Uuid id(unsigned value){std::ostringstream s;s<<"00000000-0000-0000-0000-"<<std::hex<<std::setfill('0')<<std::setw(12)<<value;return framework::Uuid(s.str());}
static std::vector<AvatarAnimationEntry> entries(int count,int mode){std::vector<AvatarAnimationEntry> out;auto source=id(999);std::int32_t values[]={0,-1,INT32_MIN,INT32_MAX,0x12345678};for(int n=0;n<count;n++){framework::Uuid object;int choice=(mode>>1)%4;if(choice==1)object=source;if(choice==2)object=id(777+n%3);if(choice==3){switch(n%4){case 0:object=id(777);break;case 1:object=source;break;case 2:object={};break;case 3:object=id(778);break;}}out.push_back({id(n%13+1),object,values[(n+mode)%5]});}return out;}
static std::string packet(int count,int mode){try{auto source=id(999);auto p=avatar_animations(source,mode&1?source:id(998),entries(count,mode));return hex(network::lludp::encode_packet(p));}catch(const std::length_error&){return "BUFFER";}catch(const std::out_of_range&){return "COUNT";}}
static std::string codec(){using namespace network;auto p=lludp::make_packet("AvatarAnimation");p.block("Sender")["ID"]=id(999);for(const auto& e:entries(255,0)){auto b=lludp::make_block(p.spec->blocks[1]);b["AnimID"]=e.animation;b["AnimSequenceID"]=std::int64_t(e.sequence);p.blocks["AnimationList"].push_back(std::move(b));}return hex(lludp::encode_packet(p));}
int main(int argc,char** argv){try{if(argc>1&&std::string(argv[1])=="--packets"){int n,mode;while(std::cin>>n>>mode)std::cout<<packet(n,mode)<<"\n";return 0;}if(argc>1&&std::string(argv[1])=="--codec255"){std::cout<<codec()<<"\n";return 0;}if(argc>2&&std::string(argv[1])=="--catalog"){DefaultAnimations catalog(argv[2]);for(const auto& [name,id]:catalog.by_name)std::cout<<"N:"<<name<<":"<<id.str()<<"\n";for(const auto& [id,name]:catalog.by_id)std::cout<<"I:"<<id.str()<<":"<<name<<"\n";for(const auto& [id,state]:catalog.states)std::cout<<"S:"<<id.str()<<":"<<state<<"\n";std::string op,value;while(std::cin>>op>>value){if(op=="R")std::cout<<catalog.resolve(unhex(value)).str()<<"\n";else std::cout<<catalog.name(framework::Uuid(value))<<"\n";}return 0;}
 if(packet(0,0).size()!=52)throw std::runtime_error("empty packet26 bytes");if(packet(203,0)=="BUFFER"||packet(204,0)!="BUFFER")throw std::runtime_error("other buffer boundary");if(packet(113,5)=="BUFFER"||packet(114,5)!="BUFFER")throw std::runtime_error("self source-object boundary");if(packet(255,0)!="BUFFER"||packet(256,0)!="COUNT")throw std::runtime_error("source capacity and count boundary");if(codec().size()!=10252)throw std::runtime_error("generic codec255 remains valid");auto a=avatar_animations(id(999),id(999),entries(4,7));auto& blocks=a.blocks.at("AnimationList");if(std::get<framework::Uuid>(blocks[0].at("AnimID"))!=id(1)||std::get<framework::Uuid>(blocks[1].at("AnimID"))!=id(4)||a.blocks.at("AnimationSourceList").size()!=2)throw std::runtime_error("stable source ordering");std::cout<<"PASS: avatar animation ordering/count/source capacity and generic255 codec\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
